        children: "flowchart TB\n    A[\"Arjuna ka vishad; dhanush gira\"] --> B[\"Krishna ka pehla jawab; chunauti\"]\n    B --> C[\"Ashochyan: roone ka bhram hatana\"]\n    C --> D[\"Atma ka gyan: na janm na mrityu\"]\n    D --> E[\"Karm ka gyan: karmanyevadhikaraste\"]\n    E --> F[\"Stithaprajna ka lakshan\"]\n    F --> G[\"Man ka chain: dhyana se patan tak\"]\n    G --> H[\"Samudra ka drishtant: poornata\"]\n    H --> I[\"Jagrukta; sakshi; sthita buddhi\"]\n    style C fill:#4446e8,color:#fff\n    style I fill:#eef0ff,color:#1a1b23\n"
